/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, Poly, Pow, Sym, add, fn, integrate, logToAtan, logToReal, mul, pow, ratint, ratintRatpart, rational, simplify, symbols } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.integrals.rationaltools", () => {
  it("log_to_atan(Poly(x, x, domain='ZZ'), Poly(1, x, domain='ZZ'))", () => {
    const x = new Sym('x');
    expect(sympyStr(logToAtan(Poly.from(x, [x], { domain: 'ZZ', pure: false }), Poly.from(rational(1), [x], { domain: 'ZZ', pure: false })))).toBe('2*atan(x)');
  });
  it("log_to_atan(Poly(x + S(1)/2, x, domain='QQ'),", () => {
    const x = new Sym('x');
    expect(sympyStr(logToAtan(Poly.from(add(rational(1, 2), x), [x], { domain: 'QQ', pure: false }), Poly.from(mul(rational(1, 2), pow(3, rational(1, 2))), [x], { domain: 'EX', pure: false })))).toBe('2*atan(2*sqrt(3)*x/3 + sqrt(3)/3)');
  });
  it("log_to_real(Poly(x + 3*y/2 + S(1)/2, x, domain='QQ[y]'),", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(logToReal(Poly.from(add(rational(1, 2), x, mul(rational(3, 2), y)), [x], { domain: 'QQ[y]', pure: false }), Poly.from(add(1, mul(3, pow(y, 2))), [y], { domain: 'ZZ', pure: false }), x, y))).toBe('2*sqrt(3)*atan(2*sqrt(3)*x/3 + sqrt(3)/3)/3');
  });
  it("log_to_real(Poly(x**2 - 1, x, domain='ZZ'),", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(logToReal(Poly.from(add(-1, pow(x, 2)), [x], { domain: 'ZZ', pure: false }), Poly.from(add(1, mul(-2, y)), [y], { domain: 'ZZ', pure: false }), x, y))).toBe('log(x**2 - 1)/2');
  });
  it("ratint(36/(x**5 - 2*x**4 - 2*x**3 + 4*x**2 + x - 2), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(ratint(mul(36, pow(add(-2, x, pow(x, 5), mul(-2, pow(x, 3)), mul(-2, pow(x, 4)), mul(4, pow(x, 2))), -1)), x))).toBe('(12*x + 6)/(x**2 - 1) + 4*log(x - 2) - 4*log(x + 1)');
  });
  // a result object that did not come from the library
  //   ratint_logpart(Poly(1, x, domain='ZZ'),
  //   Poly(x**2 + x + 1, x, domain='ZZ'), x)
  //   => [(Poly(x + 3*_t/2 + 1/2, x, domain='QQ[_t]'), Poly(3*_t**2 + 1, _t, domain='ZZ'))]
  it.todo("ratint_logpart(Poly(1, x, domain='ZZ'),");
  // a result object that did not come from the library
  //   ratint_logpart(Poly(12, x, domain='ZZ'),
  //   Poly(x**2 - x - 2, x, domain='ZZ'), x)
  //   => [(Poly(x - 3*_t/8 - 1/2, x, domain='QQ[_t]'), Poly(-_t**2 + 16, _t, domain='ZZ'))]
  it.todo("ratint_logpart(Poly(12, x, domain='ZZ'),");
  it("ratint_ratpart(Poly(1, x, domain='ZZ'),", () => {
    const x = new Sym('x');
    const v1 = ratintRatpart(Poly.from(rational(1), [x], { domain: 'ZZ', pure: false }), Poly.from(add(1, x), [x], { domain: 'ZZ', pure: false }), x);
    expect(sympyMatches([at(v1, 0), at(v1, 1)], '(0, 1/(x + 1))')).toBe(true);
  });
  it("ratint_ratpart(Poly(1, x, domain='EX'),", () => {
    const [x, y] = symbols('x y');
    const v1 = ratintRatpart(Poly.from(rational(1), [x], { domain: 'EX', pure: false }), Poly.from(add(pow(x, 2), pow(y, 2)), [x], { domain: 'EX', pure: false }), x);
    expect(sympyMatches([at(v1, 0), at(v1, 1)], '(0, 1/(x**2 + y**2))')).toBe(true);
  });
  it("ratint_ratpart(Poly(36, x, domain='ZZ'),", () => {
    const x = new Sym('x');
    const v1 = ratintRatpart(Poly.from(rational(36), [x], { domain: 'ZZ', pure: false }), Poly.from(add(-2, x, pow(x, 5), mul(-2, pow(x, 3)), mul(-2, pow(x, 4)), mul(4, pow(x, 2))), [x], { domain: 'ZZ', pure: false }), x);
    expect(sympyMatches([at(v1, 0), at(v1, 1)], '((12*x + 6)/(x**2 - 1), 12/(x**2 - x - 2))')).toBe(true);
  });
});

